  const viewBefore = await evaluate('({zoom:window.__ROAD_WORKBENCH__.getMap().getZoom(),center:window.__ROAD_WORKBENCH__.getMap().getCenter().toArray()})');
  await command('Input.dispatchMouseEvent', {type:'mouseWheel', ...gesturePoint, deltaX:0, deltaY:-120});
  await new Promise(resolve=>setTimeout(resolve,600));
  assert(await evaluate(`window.__ROAD_WORKBENCH__.getMap().getZoom()>${viewBefore.zoom}`));
  check('鼠标滚轮缩放',true);
  const panBefore=await evaluate('({zoom:window.__ROAD_WORKBENCH__.getMap().getZoom(),center:window.__ROAD_WORKBENCH__.getMap().getCenter().toArray()})');
  await command('Input.dispatchMouseEvent',{type:'mouseWheel',...gesturePoint,deltaX:18,deltaY:12});
  await new Promise(resolve=>setTimeout(resolve,200));
